    TEST_ASSERT_EQUAL_STRING(" style=\"color:#55dd99;background-color:#6b0008\"", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(2, g_d.anim_scroll);
    TEST_ASSERT_EQUAL(0, g_d.anim_view);
    TEST_ASSERT_EQUAL(0, g_d.anim_idle);
    TEST_ASSERT_EQUAL(0, g_d.geom_need);
    TEST_ASSERT_EQUAL(0, g_d.geom_used);
    geo_root(589);
    geo("html", 1, 1, 932, 100, 30, 139, 480, 640, 589, 0);
    geo("body", 1, 0, 1221, 20, 3, 298, 640, 480, 0, 589);
    geo("i", 1, 1, -40, 0, 55, 117, 480, 640, 589, 0);
    prep3("@property --p { syntax: '<length>'; inherits: false; initial-value: 0px } @keyframes k { 33.33% { color: tan } } @keyframes j { 75% { color: hsla(none none none / 1); background-color: hsl(0.3turn, 41%, 119.74%, 100%) } } #i { animation: k 2s, j 2s linear 250ms forwards; animation-timeline: view(25%) }", 0, 0, 1);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#000000;background-color:#00000000\"", style_of("i"));
    TEST_ASSERT_EQUAL(2, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.anim_scroll);
    TEST_ASSERT_EQUAL(2, g_d.anim_view);
    TEST_ASSERT_EQUAL(0, g_d.anim_idle);
    TEST_ASSERT_EQUAL(1, g_d.geom_need);
    TEST_ASSERT_EQUAL(1, g_d.geom_used);
    geo_root(400);
    geo("o", 1, 1, 377, 20, 55, 634, 480, 640, 400, 0);
    prep3("@property --p { syntax: '<length>'; inherits: false; initial-value: 0px } @keyframes k { 50% { color: red; background-color: color-mix(in srgb, rgb(none 158 none), hsla(146.88deg 50% none)) } } @keyframes j { 33.33% { background-color: black } 60% { color: oklab(none 1 -0.872 -0.3778); background-color: hwb(none 31 none/50%) } to { color: red } } html { view-timeline-name: --t; view-timeline-axis: x; view-timeline-inset: -107.583px, 100001px } body { view-timeline-name: --v, --t; view-timeline-axis: block; view-timeline-inset: auto 5, auto, 14.81px auto; view-timeline-inset: initial } #i { animation: k 1000ms 500ms forwards, k 2s linear; animation-timeline: --t, view(10px); animation-range-start: cover -5px; animation-range-end: entry } #q { view-timeline: --v 1in, --u; view-timeline-inset: auto -124.92px, 99999px -229.1px, auto, 12.34567px, 12.34567px }", 0, 7500, 1);
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.anim_scroll);
    TEST_ASSERT_EQUAL(0, g_d.anim_view);
    TEST_ASSERT_EQUAL(2, g_d.anim_idle);
    TEST_ASSERT_EQUAL(2, g_d.geom_need);
    TEST_ASSERT_EQUAL(0, g_d.geom_used);
    geo_clear();
    prep3("@property --p { syntax: '<length>'; inherits: false; initial-value: 0px } @keyframes k { 50% { background-color: #a4db } 60% { background-color: rgb(43% 37 77) } 75% { color: hsla(none none 37%); background-color: forestgreen } } html { scroll-timeline: --t; scroll-timeline-name: auto; view-timeline-name: --u; view-timeline: --t; view-timeline-inset: 12.34567px,-5px,150% } #i { animation: k 500ms linear, k 500ms linear; animation-timeline: --t; animation-range: 0% }", 0, 2500, 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#1f1f1f;background-color:#aa44dd5e\"", style_of("i"));
    TEST_ASSERT_EQUAL(2, g_d.col_animated);
    TEST_ASSERT_EQUAL(2, g_d.anim_scroll);
